const cap=v=>String(v||'').charAt(0).toUpperCase()+String(v||'').slice(1);
const pct=v=>`${Math.max(0,Math.min(100,Math.round(Number(v)||0)))}%`;
const hay=(...v)=>v.filter(Boolean).join(' ').toLowerCase();
const toLocalInput=v=>{const ms=timestampMs(v);if(!ms)return'';const d=new Date(ms),pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`};
function useLoad(fn,deps=[]){const[d,setD]=useState(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[tick,setTick]=useState(0);useEffect(()=>{let alive=true;setLoading(true);setError('');Promise.resolve().then(fn).then(x=>alive&&setD(x)).catch(e=>{console.error(e);alive&&setError(e?.message||'Unable to load data.')}).finally(()=>alive&&setLoading(false));return()=>{alive=false}},[tick,...deps]);return{data:d,loading,error,refresh:()=>setTick(v=>v+1)}}
function Page({eyebrow,title,text,action}){return <div className="page-title"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1>{text&&<p>{text}</p>}</div>{action}</div>}
function Loading(){return <div className="panel functional-state"><RefreshCw className="spin"/><strong>Loading EqualLearn…</strong></div>}
function Failure({message,retry}){return <div className="panel functional-state"><strong>Unable to load this page</strong><p>{message}</p>{retry&&<button className="btn ghost small" onClick={retry}>Retry</button>}</div>}
function Empty({title='Nothing here yet',text}){return <div className="empty-live"><CheckCircle2/><strong>{title}</strong>{text&&<p>{text}</p>}</div>}
function Stat({label,value,detail,Icon}){return <article className="stat-card">{Icon&&<span className="stat-icon"><Icon/></span>}<div><span>{label}</span><strong>{value}</strong>{detail&&<small>{detail}</small>}</div></article>}
function Bar({value}){return <div className="progress"><i style={{width:pct(value)}}/></div>}
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Notice({children,type='info'}){return children?<div className={`form-message ${type}`}>{children}</div>:null}
function PasswordInput(props){const[show,setShow]=useState(false);return <div className="password-input"><input {...props} type={show?'text':'password'}/><button type="button" className="password-toggle" onClick={()=>setShow(v=>!v)} aria-label={show?'Hide password':'Show password'}>{show?<EyeOff size={16}/>:<Eye size={16}/>}<span>{show?'Hide':'Show'}</span></button></div>}
function Modal({open,title,onClose,children,wide=false}){if(!open)return null;return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className={`modal-card ${wide?'wide':''}`}><div className="modal-head"><h2>{title}</h2><button className="icon-btn" onClick={onClose}><X/></button></div>{children}</div></div>}
function Table({headers,rows,empty='No records found.'}){return <div className="responsive-table"><div className="table-grid table-head" style={{'--cols':headers.length}}>{headers.map(h=><span key={h}>{h}</span>)}</div>{rows.length?rows.map((r,i)=><div className="table-grid" style={{'--cols':headers.length}} key={r.key||i}>{r.cells.map((c,j)=><div key={j}>{c}</div>)}</div>):<Empty title={empty}/>}</div>}
function sectionOf(person){
  if(!person)return '—';
  return studentSection(person)||'—';
}
function academicProfile(person){
  return {
    course: studentCourse(person),
    yearLevel: normalizeYearLevel(person?.yearLevel)||'—',
    section: sectionOf(person),
  };
}
function ProfileView({person,role,section,actions,compact=false}){
  const resolvedRole=cap(role||person?.role||'user');
  const isStudent=lower(role||person?.role)==='student';
  const academic=academicProfile(person);
  return <section className={`profile-view ${compact?'compact':''}`}>
    <div className="profile-view-identity">
      <ProfileAvatar size={compact?'lg':'xl'} profileOverride={person}/>
      <div><span className="mini-label">PROFILE</span><h2>{person?.fullname||person?.email||'EqualLearn user'}</h2><p>{person?.studentNumber||person?.title||person?.department||'EqualLearn account'}</p></div>
    </div>
    <div className="profile-view-facts">
      <div><span>Role</span><strong>{resolvedRole}</strong></div>
      {isStudent&&<div><span>Course</span><strong>{academic.course}</strong></div>}
      {isStudent&&<div><span>Year Level</span><strong>{academic.yearLevel}</strong></div>}
      <div><span>Section</span><strong>{section||academic.section}</strong></div>
      <div><span>Email</span><strong>{person?.email||'—'}</strong></div>
      <div><span>Phone</span><strong>{person?.phone||'—'}</strong></div>
    </div>
    <div className="profile-view-bio"><span>Bio</span><p>{person?.bio||'No bio added yet.'}</p></div>
    {actions&&<div className="profile-view-actions">{actions}</div>}
  </section>
}

async function studentBundle(uid,profile){const[modules,lessons,questions,progress,assignment]=await Promise.all([getModules(),getLessons(),getQuestions(),getProgress(uid),getStudentAssignment(profile)]);return{modules,lessons,questions,progress,assignment}}

export function StudentDashboard(){const{firebaseUser,profile}=useAuth();const l=useLoad(()=>studentBundle(firebaseUser.uid,profile),[firebaseUser.uid,profile?.course,profile?.yearLevel,profile?.section,profile?.cohort]);if(l.loading)return <AppShell role="student"><Loading/></AppShell>;if(l.error)return <AppShell role="student"><Failure message={l.error} retry={l.refresh}/></AppShell>;const{modules,lessons,questions,progress,assignment}=l.data;const s=progressSummary(progress,questions),done=new Set(progress.filter(p=>p.completed).map(p=>p.lessonId));const ms=modules.filter(m=>!['inactive','draft'].includes(lower(m.status||'active'))).map(m=>{const ls=lessons.filter(x=>x.moduleId===m.id),d=ls.filter(x=>done.has(x.id)).length;return{...m,lessons:ls,done:d,percent:ls.length?Math.round(d/ls.length*100):0}}),next=ms.find(m=>m.percent<100)||ms[0];return <AppShell role="student"><Page eyebrow="Student home" title={`Hello, ${(profile?.fullname||'Student').split(' ')[0]}.`} text="Continue learning, check your class, and see your real assessment progress."/><div className="stats-grid"><Stat label="Quiz completion" value={pct(s.percent)} detail={`${s.completed}/${s.total} quiz lessons`} Icon={ClipboardCheck}/><Stat label="Average score" value={pct(s.average)} detail={`${s.attempts} saved attempts`} Icon={BarChart3}/><Stat label="Section" value={sectionOf(profile)} detail={assignment?.teacherName?`Teacher: ${assignment.teacherName}`:'No teacher assigned'} Icon={Users}/></div><div className="dashboard-grid section-gap"><section className="panel"><span className="mini-label">CONTINUE LEARNING</span><h2>{next?.title||'No module yet'}</h2>{next?<><p>{next.description||'Continue your next lesson.'}</p><Bar value={next.percent}/><div className="progress-meta"><span>{next.done}/{next.lessons.length} lessons</span><strong>{pct(next.percent)}</strong></div><Link className="btn primary small" to={`/student/learning/${next.id}`}>Continue <ArrowRight/></Link></>:<Empty title="No published modules"/>}</section><section className="panel"><span className="mini-label">ACADEMIC PROFILE</span><h2>Student details</h2><div className="detail-list"><div><span>Section</span><strong>{sectionOf(profile)}</strong></div><div><span>Course</span><strong>{studentCourse(profile)}</strong></div><div><span>Year Level</span><strong>{normalizeYearLevel(profile?.yearLevel)||'—'}</strong></div><div><span>Teacher</span><strong>{assignment?.teacherName||'—'}</strong></div></div></section></div></AppShell>}

export function StudentLearning(){const{firebaseUser}=useAuth();const[search,setSearch]=useState(''),[filter,setFilter]=useState('all');const l=useLoad(async()=>{const[m,ls,p]=await Promise.all([getModules(),getLessons(),getProgress(firebaseUser.uid)]);return{m,ls,p}},[firebaseUser.uid]);if(l.loading)return <AppShell role="student"><Loading/></AppShell>;const done=new Set((l.data?.p||[]).filter(p=>p.completed).map(p=>p.lessonId));let rows=(l.data?.m||[]).filter(m=>!['inactive','draft'].includes(lower(m.status||'active'))).map(m=>{const lessons=l.data.ls.filter(x=>x.moduleId===m.id),d=lessons.filter(x=>done.has(x.id)).length;return{...m,lessons,done:d,percent:lessons.length?Math.round(d/lessons.length*100):0}});if(search)rows=rows.filter(x=>hay(x.title,x.description).includes(lower(search)));if(filter==='progress')rows=rows.filter(x=>x.percent>0&&x.percent<100);if(filter==='completed')rows=rows.filter(x=>x.lessons.length&&x.percent===100);return <AppShell role="student"><Page eyebrow="Learning" title="Your learning path" text="Open modules, resources, and lesson quizzes from one place."/><div className="toolbar"><div className="searchbox"><Search/><input placeholder="Search modules…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="segmented-options">{[['all','All'],['progress','In progress'],['completed','Completed']].map(([id,label])=><button className={filter===id?'active':''} onClick={()=>setFilter(id)} key={id}>{label}</button>)}</div></div><div className="content-card-grid section-gap">{rows.map(m=><Link className="content-card clickable" to={`/student/learning/${m.id}`} key={m.id}><div className="card-meta"><span className="chip">Order {m.order||1}</span><span className="chip">{m.lessons.length} lessons</span></div><h3>{m.title}</h3><p>{m.description||'No description.'}</p><Bar value={m.percent}/><small>{m.done}/{m.lessons.length} completed · {pct(m.percent)}</small></Link>)}</div>{!rows.length&&<section className="panel"><Empty title="No modules match this view"/></section>}</AppShell>}

export function StudentModuleDetails(){const{moduleId}=useParams(),{firebaseUser}=useAuth();const l=useLoad(async()=>{const[m,ls,q,p,d,o]=await Promise.all([getModules(),getLessons(),getQuestions(),getProgress(firebaseUser.uid),getDeadlines(),getDeadlineOverrides(firebaseUser.uid)]);return{module:m.find(x=>x.id===moduleId),lessons:ls.filter(x=>x.moduleId===moduleId),questions:q,progress:p,deadlines:d,overrides:o}},[moduleId,firebaseUser.uid]);if(l.loading)return <AppShell role="student"><Loading/></AppShell>;if(!l.data?.module)return <AppShell role="student"><Empty title="Module unavailable"/></AppShell>;const{module,lessons,questions,progress,deadlines,overrides}=l.data,pm=new Map(progress.map(p=>[p.lessonId,p]));return <AppShell role="student"><Link className="text-link" to="/student/learning"><ArrowLeft/> Learning</Link><Page eyebrow="Module" title={module.title} text={module.description}/>{module.fileURL&&<section className="panel resource-banner"><FileText/><div><strong>{module.fileName||'Module resource'}</strong></div><a className="btn ghost small" href={module.fileURL} target="_blank" rel="noreferrer">Open <ExternalLink/></a></section>}<section className="panel section-gap"><h2>Lessons</h2><div className="stack-list">{lessons.map((x,i)=>{const qc=questions.filter(q=>q.lessonId===x.id).length,p=pm.get(x.id),due=deadlineFor(deadlines,overrides,x.id,firebaseUser.uid),dueInfo=dueState(due.dueAt);return <article className="management-row" key={x.id}><span className={`lesson-index ${p?.completed?'done':''}`}>{p?.completed?<Check/>:i+1}</span><div><strong>{x.title}</strong><p>{x.description||'No description.'}</p><div className="card-meta">{dueInfo.label&&<span className={`chip ${dueInfo.overdue&&!p?.completed?'danger-chip':''}`}>{due.personal?'Moved: ':''}{dueInfo.label}</span>}{due.personal&&<span className="chip">Adjusted by teacher</span>}{qc>0&&<span className="chip">{qc} questions</span>}{p&&<span className="chip">Last {pct(p.percentage)}</span>}</div></div><div className="row-actions">{x.fileUrl&&<a className="icon-btn" href={x.fileUrl} target="_blank" rel="noreferrer"><FileText/></a>}{x.videoUrl&&<a className="icon-btn" href={x.videoUrl} target="_blank" rel="noreferrer"><Video/></a>}{qc>0&&<Link className="btn primary small" to={`/student/quiz/${x.id}`}>{p?'Retake':'Take quiz'}</Link>}</div></article>})}{!lessons.length&&<Empty title="No lessons yet"/>}</div></section></AppShell>}
export function StudentQuizzes(){const{firebaseUser}=useAuth();const[search,setSearch]=useState(''),[filter,setFilter]=useState('all');const l=useLoad(async()=>{const[ls,q,p]=await Promise.all([getLessons(),getQuestions(),getProgress(firebaseUser.uid)]);return{ls,q,p}},[firebaseUser.uid]);if(l.loading)return <AppShell role="student"><Loading/></AppShell>;const pm=new Map((l.data?.p||[]).map(p=>[p.lessonId,p]));let rows=(l.data?.ls||[]).map(x=>({...x,count:l.data.q.filter(q=>q.lessonId===x.id).length,progress:pm.get(x.id)})).filter(x=>x.count);if(search)rows=rows.filter(x=>hay(x.title,x.moduleName).includes(lower(search)));if(filter==='available')rows=rows.filter(x=>!x.progress);if(filter==='completed')rows=rows.filter(x=>x.progress);return <AppShell role="student"><Page eyebrow="Quizzes" title="Check what you know" text="Take lesson quizzes and review your latest saved result."/><div className="toolbar"><div className="searchbox"><Search/><input placeholder="Search quizzes…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="segmented-options">{[['all','All'],['available','Available'],['completed','Completed']].map(([id,label])=><button className={filter===id?'active':''} onClick={()=>setFilter(id)} key={id}>{label}</button>)}</div></div><div className="content-card-grid section-gap">{rows.map(x=><article className="content-card" key={x.id}><span className="chip">{x.moduleName||'Lesson quiz'}</span><h3>{x.title}</h3><p>{x.progress?`Last score: ${pct(x.progress.percentage)} · ${cap(x.progress.result)}`:`${x.count} questions · No attempt yet`}</p><Link className="btn primary small" to={`/student/quiz/${x.id}`}>{x.progress?'Retake':'Start quiz'} <ArrowRight/></Link></article>)}</div></AppShell>}

export function StudentQuiz(){
  const{lessonId}=useParams(),{firebaseUser}=useAuth(),nav=useNavigate();
  const[index,setIndex]=useState(0),[selected,setSelected]=useState(''),[answers,setAnswers]=useState([]),[result,setResult]=useState(null),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false),[remaining,setRemaining]=useState(null);
  const deadlineRef=useRef(0),submitRef=useRef(null),doneRef=useRef(false);
  const l=useLoad(async()=>{const[ls,q,z,p,d,o]=await Promise.all([getLessons(),getQuestions(),getQuizzes(),getProgress(firebaseUser.uid),getDeadlines(),getDeadlineOverrides(firebaseUser.uid)]);return{lesson:ls.find(x=>x.id===lessonId),questions:q.filter(x=>x.lessonId===lessonId),settings:quizSettingsFor(z,lessonId),progress:p.find(x=>x.lessonId===lessonId)||null,deadline:deadlineFor(d,o,lessonId,firebaseUser.uid)}},[lessonId,firebaseUser.uid]);
  const settings=l.data?.settings||DEFAULT_QUIZ_SETTINGS;
  const rawQs=l.data?.questions||[];
  const qs=useMemo(()=>settings.shuffleQuestions?shuffleList(rawQs):rawQs,[rawQs,settings.shuffleQuestions,lessonId]);
  const attemptsUsed=Number(l.data?.progress?.attempts||0);
  const attemptsLeft=settings.attemptsAllowed>0?Math.max(0,settings.attemptsAllowed-attemptsUsed):null;
  const timed=settings.timeLimitMinutes>0;
  async function finish(list,timedOut=false){
    if(doneRef.current||result)return;
    doneRef.current=true;setBusy(true);
    try{
      const spent=timed?Math.max(0,Math.round(settings.timeLimitMinutes*60-(remaining??0))):0;
      const saved=await saveQuizProgress({uid:firebaseUser.uid,lessonId,score:list.filter(x=>x.correct).length,total:qs.length,passingScore:settings.passingScore,attemptsUsed,timeSpentSeconds:spent});
      setResult({...saved,timedOut,review:list});
    }catch(e){doneRef.current=false;setMsg(e?.message||'Unable to save your result.')}finally{setBusy(false)}
  }
  useEffect(()=>{
    if(l.loading||!l.data||result||!timed)return;
    if(!deadlineRef.current)deadlineRef.current=Date.now()+settings.timeLimitMinutes*60000;
    const tick=()=>{const left=Math.max(0,Math.ceil((deadlineRef.current-Date.now())/1000));setRemaining(left);if(left<=0&&submitRef.current)submitRef.current()};
    tick();const id=setInterval(tick,1000);return()=>clearInterval(id);
  },[l.loading,l.data,result,timed,settings.timeLimitMinutes]);
  useEffect(()=>{submitRef.current=()=>finish(answers,true)},[answers,busy,result,settings.passingScore,qs.length,timed]);
  if(l.loading)return <AppShell role="student"><Loading/></AppShell>;
  if(!rawQs.length)return <AppShell role="student"><Empty title="No questions available"/></AppShell>;
  const lessonTitle=l.data.lesson?.title||'Quiz';
  if(attemptsLeft===0&&!result)return <AppShell role="student"><Page eyebrow="Quiz" title={lessonTitle} text="This quiz has an attempt limit."/><section className="panel functional-state"><strong>No attempts left</strong><p>You have used all {settings.attemptsAllowed} allowed attempt{settings.attemptsAllowed===1?'':'s'} for this quiz. Best saved score: {pct(l.data.progress?.bestPercentage ?? l.data.progress?.percentage ?? 0)}.</p><button className="btn ghost small" onClick={()=>nav('/student/quizzes')}>Back to quizzes</button></section></AppShell>;
  if(result){
    const passed=result.result==='passing';
    return <AppShell role="student">
      <Page eyebrow="Quiz complete" title={passed?'You passed.':'Keep reviewing.'} text={`${result.score}/${result.total} correct · ${pct(result.percentage)} · pass mark ${pct(result.passingScore ?? settings.passingScore)}`}/>
      <section className="panel quiz-result"><div className={`result-ring ${result.result}`}><strong>{pct(result.percentage)}</strong><span>{cap(result.result)}</span></div><div><h2>{lessonTitle}</h2><p>{result.timedOut?'Time is up — your answers were submitted automatically. ':'Your latest result was saved to Firestore. '}{result.attempts?`Attempt ${result.attempts}${settings.attemptsAllowed?` of ${settings.attemptsAllowed}`:''}.`:''}</p><div className="card-actions">{(attemptsLeft===null||attemptsLeft>0)&&<button className="btn ghost" onClick={()=>{setIndex(0);setAnswers([]);setSelected('');setResult(null);setMsg('');doneRef.current=false;deadlineRef.current=0}}>Retake</button>}<button className="btn primary" onClick={()=>nav('/student/progress')}>View progress</button></div></div></section>
      {settings.showAnswersAfter&&(result.review?.length||0)>0&&<section className="panel section-gap"><h2>Answer review</h2><div className="stack-list">{result.review.map((row,i)=><article className="management-row" key={row.questionId||i}><span className={`lesson-index ${row.correct?'done':''}`}>{row.correct?<Check/>:<X/>}</span><div><strong>{i+1}. {row.question}</strong><p>{row.selected?`Your answer: ${row.selected}. ${row.selectedText}`:'No answer submitted'} · Correct: {row.correctAnswer}. {row.correctText}</p></div></article>)}{qs.length>result.review.length&&<p className="muted small">Skipped questions were marked as incorrect.</p>}</div></section>}
    </AppShell>;
  }
  const q=qs[index],choices=[['A',q.choiceA],['B',q.choiceB],['C',q.choiceC],['D',q.choiceD]];
  const clock=timed&&remaining!==null?`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`:'';
  const dueInfo=dueState(l.data.deadline?.dueAt);
  async function next(){
    if(!selected){setMsg('Choose an answer first.');return}
    const a=[...answers,{questionId:q.id,question:q.question,selected,selectedText:q[`choice${selected}`]||'',correctAnswer:q.correctAnswer,correctText:q[`choice${q.correctAnswer}`]||'',correct:selected===q.correctAnswer}];
    if(index<qs.length-1){setAnswers(a);setIndex(v=>v+1);setSelected('');setMsg('');return}
    await finish(a);
  }
  return <AppShell role="student"><button className="text-link button-link" onClick={()=>nav(-1)}><ArrowLeft/> Exit quiz</button><Page eyebrow={`Question ${index+1} of ${qs.length}`} title={lessonTitle} text="Choose one answer before continuing."/><section className="panel quiz-panel"><div className="quiz-meta"><Bar value={index/qs.length*100}/>{timed?<span className={`chip ${remaining!==null&&remaining<=30?'danger-chip':''}`}>Time left {clock}</span>:null}<span className="chip">{settings.attemptsAllowed?`Attempt ${Math.min(attemptsUsed+1,settings.attemptsAllowed)} of ${settings.attemptsAllowed}`:'Unlimited attempts'}</span>{dueInfo.label&&<span className={`chip ${dueInfo.overdue?'danger-chip':''}`}>{l.data.deadline?.personal?'Moved: ':''}{dueInfo.label}</span>}<span className="chip">Pass {pct(settings.passingScore)}</span></div><h2>{q.question}</h2><div className="quiz-choices">{choices.map(([k,v])=><button className={selected===k?'selected':''} onClick={()=>{setSelected(k);setMsg('')}} key={k}><span>{k}</span><strong>{v}</strong></button>)}</div><Notice type="error">{msg}</Notice><div className="quiz-next"><button className="btn primary" onClick={next} disabled={busy}>{index===qs.length-1?(busy?'Saving…':'Finish quiz'):'Next question'} <ArrowRight/></button></div></section></AppShell>
}

export function StudentProgress(){const{firebaseUser}=useAuth();const l=useLoad(async()=>{const[p,ls,q]=await Promise.all([getProgress(firebaseUser.uid),getLessons(),getQuestions()]);return{p,ls,q}},[firebaseUser.uid]);if(l.loading)return <AppShell role="student"><Loading/></AppShell>;const s=progressSummary(l.data.p,l.data.q),lm=new Map(l.data.ls.map(x=>[x.id,x]));return <AppShell role="student"><Page eyebrow="Progress" title="Your learning record" text="Real saved quiz results from the existing progress collection."/><div className="stats-grid"><Stat label="Quiz completion" value={pct(s.percent)} detail={`${s.completed}/${s.total}`} Icon={CheckCircle2}/><Stat label="Average score" value={pct(s.average)} Icon={BarChart3}/><Stat label="Passing results" value={s.passed} Icon={GraduationCap}/></div><section className="panel section-gap"><div className="stack-list">{l.data.p.map(p=>{const lesson=lm.get(p.lessonId)||{};return <article className="management-row" key={p.id}><span className={`lesson-index ${p.result==='passing'?'done':''}`}>{p.result==='passing'?<Check/>:<ClipboardCheck/>}</span><div><strong>{lesson.title||'Lesson'}</strong><p>{lesson.moduleName||'Learning module'} · {p.score}/{p.total} · {formatWhen(p.completedAt)}</p><Bar value={p.percentage}/></div><div className="row-actions"><span className="chip">{pct(p.percentage)}</span><Link className="btn ghost small" to={`/student/quiz/${p.lessonId}`}>Retake</Link></div></article>})}{!l.data.p.length&&<Empty title="No progress recorded yet"/>}</div></section></AppShell>}

export function StudentProfile(){
  const{firebaseUser,profile,refreshProfile}=useAuth();
  const initial=nameParts(profile);
  const[f,setF]=useState({...initial,course:studentCourse(profile),yearLevel:normalizeYearLevel(profile?.yearLevel)||'',section:studentSection(profile)||'',phone:profile?.phone||'',bio:profile?.bio||''}),[msg,setMsg]=useState('');
  const set=(k,v)=>setF(x=>({...x,[k]:v}));
  const setName=v=>setF(x=>({...x,...v}));
  const setSection=v=>set('section',normalizeSection(v));
  async function save(e){
    e.preventDefault();
    const firstName=normalizePersonName(f.firstName),middleInitial=normalizeMiddleInitial(f.middleInitial),lastName=normalizePersonName(f.lastName),course=normalizeCourse(f.course);
    if(!firstName||!lastName){setMsg('Enter your first and last name.');return;}
    if(!course){setMsg('Enter your course, for example BSIT.');return;}
    if(!YEAR_LEVELS.includes(f.yearLevel)){setMsg('Choose 1st, 2nd, 3rd, or 4th year.');return;}
    if(!f.section){setMsg('Section must contain 1 to 3 letters or numbers.');return;}
    const fullname=fullNameFromParts({firstName,middleInitial,lastName});
    await saveProfile(firebaseUser.uid,{firstName,middleInitial,lastName,fullname,course,yearLevel:f.yearLevel,section:f.section,classGroupId:`SECTION_${course}_${f.section}`,phone:f.phone.trim(),bio:f.bio.trim()});
    await refreshProfile();setMsg('Profile updated successfully.');
  }
  const preview={...profile,...f,fullname:fullNameFromParts(f)||profile?.fullname,course:normalizeCourse(f.course)||studentCourse(profile)};
  return <AppShell role="student"><Page eyebrow="Profile" title="Your student profile" text="Keep your contact details and academic information current."/>
    <div className="profile-layout refined-profile-layout">
      <section className="panel profile-summary refined-profile-summary"><ProfileAvatar size="xl" editable/><ProfileView person={preview} role="student" section={f.section}/></section>
      <form className="panel form-panel profile-edit-panel" onSubmit={save}>
        <div className="section-row"><div><span className="mini-label">PROFILE DETAILS</span><h2>Edit information</h2></div><small>Course, year level, and section are stored as separate profile values.</small></div>
        <NameFields value={f} onChange={setName} required idPrefix="student"/>
        <Field label="Email"><input value={profile?.email||''} readOnly/></Field>
        <Field label="Student number"><input value={profile?.studentNumber||''} readOnly/></Field>
        <div className="field-grid">
          <CourseField value={f.course} onChange={v=>set('course',v)} required hint="Saved with your section to build your class group."/>
          <Field label="Year Level"><select value={f.yearLevel} onChange={e=>set('yearLevel',e.target.value)} required><option value="">Select year</option>{YEAR_LEVELS.map(y=><option value={y} key={y}>{y}</option>)}</select></Field>
          <Field label="Section" hint="1 to 3 letters or numbers"><input value={f.section} onChange={e=>setSection(e.target.value)} maxLength="3" pattern="[A-Za-z0-9]{1,3}" placeholder="A, 3A, 3A1" required/></Field>
          <Field label="Phone"><input value={f.phone} onChange={e=>set('phone',e.target.value)} placeholder="Optional contact number"/></Field>
        </div>
        <Field label="Bio"><textarea rows="5" value={f.bio} onChange={e=>set('bio',e.target.value)} placeholder="A short introduction about yourself."/></Field>
        <Notice type={msg.includes('successfully')?'success':'error'}>{msg}</Notice><button className="btn primary"><Save/> Save changes</button>
      </form>
    </div>
  </AppShell>
}

async function teacherBundle(uid){const[m,ls,q,users,a,p,z]=await Promise.all([getModules(),getLessons(),getQuestions(),getUsers(),getAssignments(),getProgress(),getQuizzes()]);const modules=m.filter(x=>!x.createdBy||x.createdBy===uid),lessons=ls.filter(x=>!x.createdBy||x.createdBy===uid),lessonIds=new Set(lessons.map(x=>x.id)),questions=q.filter(x=>!x.createdBy||x.createdBy===uid||lessonIds.has(x.lessonId)),students=assignedStudentsForTeacher(uid,users,a),studentIds=new Set(students.map(x=>x.id));return{modules,lessons,questions,students,assignments:a,quizzes:z,progress:p.filter(x=>studentIds.has(x.userId)&&(!lessonIds.size||lessonIds.has(x.lessonId)))}}

export function TeacherDashboard(){const{firebaseUser,profile}=useAuth();const l=useLoad(()=>teacherBundle(firebaseUser.uid),[firebaseUser.uid]);if(l.loading)return <AppShell role="teacher"><Loading/></AppShell>;if(l.error)return <AppShell role="teacher"><Failure message={l.error} retry={l.refresh}/></AppShell>;const{modules,lessons,questions,students,progress}=l.data;const expected=Math.max(students.length*Math.max(lessons.length,1),1),uniqueCompleted=new Set(progress.filter(p=>p.completed).map(p=>`${p.userId}:${p.lessonId}`)),participants=new Set(progress.map(p=>p.userId)),activeWeek=new Set(progress.filter(p=>timestampMs(p.completedAt)>Date.now()-7*86400000).map(p=>p.userId)),average=progress.length?Math.round(progress.reduce((sum,p)=>sum+Number(p.percentage||0),0)/progress.length):0,completion=students.length&&lessons.length?Math.round(uniqueCompleted.size/expected*100):0,participation=students.length?Math.round(participants.size/students.length*100):0,weekly=students.length?Math.round(activeWeek.size/students.length*100):0;return <AppShell role="teacher"><Page eyebrow="Teacher workspace" title={`Welcome, ${(profile?.fullname||'Teacher').split(' ')[0]}.`} text="Manage learning content, students, quizzes, and real class activity."/><div className="stats-grid"><Stat label="Students" value={students.length} detail="Assigned / visible learners" Icon={Users}/><Stat label="Modules" value={modules.length} detail={`${lessons.length} lessons`} Icon={BookOpen}/><Stat label="Quiz questions" value={questions.length} detail={`${new Set(questions.map(q=>q.lessonId)).size} quiz lessons`} Icon={ClipboardCheck}/><Stat label="Average score" value={pct(average)} detail={`${progress.length} saved results`} Icon={BarChart3}/></div><section className="panel section-gap engagement-panel"><div className="section-row"><div><span className="mini-label">CLASS ENGAGEMENT</span><h2>Live learning activity</h2></div><small>{progress.length?`${participants.size} of ${students.length} students with recorded activity`:'No activity recorded yet'}</small></div><div className="engagement-metric-grid">{[['Lesson completion',completion],['Quiz participation',participation],['Average quiz score',average],['Active this week',weekly]].map(([label,value])=><div className="engagement-metric" key={label}><div><span>{label}</span><strong>{pct(value)}</strong></div><Bar value={value}/></div>)}</div></section><div className="dashboard-grid section-gap"><section className="panel"><span className="mini-label">QUICK ACTIONS</span><h2>Teaching tools</h2><div className="management-list">{[[BookOpen,'Learning Content','Create modules, lessons, and resources.','/teacher/learning-content'],[ClipboardCheck,'Quiz Builder','Create and maintain lesson questions.','/teacher/quizzes'],[Users,'Students','Review assigned learners and quiz history.','/teacher/students']].map(([I,t,d,to])=><Link className="management-row" to={to} key={t}><span className="management-icon"><I/></span><div><strong>{t}</strong><p>{d}</p></div><ChevronRight/></Link>)}</div></section><section className="panel"><span className="mini-label">RECENT RESULTS</span><h2>Latest student activity</h2><div className="stack-list compact">{progress.slice(0,6).map(p=>{const student=students.find(x=>x.id===p.userId),lesson=lessons.find(x=>x.id===p.lessonId);return <div className="activity-row" key={p.id}><span className="activity-dot"/><div><strong>{student?.fullname||'Student'}</strong><p>{lesson?.title||'Lesson'} · {pct(p.percentage)}</p></div><small>{formatWhen(p.completedAt)}</small></div>})}{!progress.length&&<Empty title="No class activity yet"/>}</div></section></div></AppShell>}

export function TeacherLearning(){
  const{firebaseUser}=useAuth();
  const l=useLoad(()=>teacherBundle(firebaseUser.uid),[firebaseUser.uid]);
  const[tab,setTab]=useState('modules'),[search,setSearch]=useState(''),[edit,setEdit]=useState(null),[msg,setMsg]=useState(''),[uploading,setUploading]=useState(false);
  if(l.loading)return <AppShell role="teacher"><Loading/></AppShell>;
  const{modules,lessons}=l.data||{modules:[],lessons:[]};
  const mm=modules.filter(x=>!search||hay(x.title,x.description).includes(lower(search))),ll=lessons.filter(x=>!search||hay(x.title,x.description,x.moduleName).includes(lower(search)));
  const openModule=m=>setEdit({type:'module',id:m?.id||'',title:m?.title||'',description:m?.description||'',order:m?.order||modules.length+1,status:m?.status||'active',fileURL:m?.fileURL||'',fileName:m?.fileName||'',fileId:m?.fileId||'',fileType:m?.fileType||'',fileSize:m?.fileSize||0,pendingFile:null});
  const openLesson=x=>setEdit({type:'lesson',id:x?.id||'',moduleId:x?.moduleId||modules[0]?.id||'',title:x?.title||'',description:x?.description||'',fileUrl:x?.fileUrl||'',fileName:x?.fileName||'',fileId:x?.fileId||'',fileType:x?.fileType||'',fileSize:x?.fileSize||0,videoUrl:x?.videoUrl||'',pendingFile:null});
  async function save(){
    try{
      setUploading(true); setMsg('');
      let payload={...edit};
      if(edit?.pendingFile){
        const uploaded=await uploadWebFile(edit.pendingFile);
        payload={...payload,fileName:uploaded.name,fileId:uploaded.id,fileType:uploaded.mimeType,fileSize:uploaded.size,filePath:`appwrite:${uploaded.id}`};
        if(edit.type==='module')payload.fileURL=uploaded.viewUrl;else payload.fileUrl=uploaded.viewUrl;
      }
      delete payload.pendingFile;
      if(edit.type==='module'){
        if(!edit.title.trim())throw new Error('Enter a module title.');
        await saveModule({...payload,uid:firebaseUser.uid});
      }else{
        if(!edit.moduleId||!edit.title.trim())throw new Error('Choose a module and enter a lesson title.');
        const m=modules.find(x=>x.id===edit.moduleId);
        await saveLesson({...payload,uid:firebaseUser.uid,moduleName:m?.title||''});
      }
      setEdit(null);setMsg('Saved successfully.');l.refresh();
    }catch(e){setMsg(e?.message||'Unable to save content.')}finally{setUploading(false)}
  }
  async function rmModule(id){if(lessons.some(x=>x.moduleId===id)){alert('Move or delete lessons inside this module first.');return}if(confirm('Delete this module?')){await deleteModule(id);l.refresh()}}
  async function rmLesson(id){if(confirm('Delete this lesson? Quiz questions are not deleted automatically.')){await deleteLesson(id);l.refresh()}}
  const fileInfo=e=>{const f=e.target.files?.[0];if(f)setEdit(v=>({...v,pendingFile:f,fileName:f.name}))};
  return <AppShell role="teacher">
    <Page eyebrow="Learning Content" title="Content library" text="Create modules, lessons, external links, and Appwrite-hosted learning attachments." action={<button className="btn primary" onClick={()=>tab==='lessons'?openLesson():openModule()}><Plus/> Add {tab==='lessons'?'lesson':'module'}</button>}/>
    <div className="toolbar"><div className="segmented-options"><button className={tab==='modules'?'active':''} onClick={()=>setTab('modules')}>Modules</button><button className={tab==='lessons'?'active':''} onClick={()=>setTab('lessons')}>Lessons</button><button className={tab==='resources'?'active':''} onClick={()=>setTab('resources')}>Resources</button></div><div className="searchbox"><Search/><input placeholder="Search content…" value={search} onChange={e=>setSearch(e.target.value)}/></div></div>
    <Notice type="success">{msg==='Saved successfully.'?msg:''}</Notice>
    {tab==='modules'&&<div className="content-card-grid section-gap">{mm.map(m=><article className="content-card" key={m.id}><div className="card-meta"><span className="chip">Order {m.order||1}</span><span className="chip">{m.status||'active'}</span><span className="chip">{lessons.filter(x=>x.moduleId===m.id).length} lessons</span>{m.fileId&&<span className="chip">Appwrite file</span>}</div><h3>{m.title}</h3><p>{m.description||'No description.'}</p>{m.fileURL&&<a className="text-link" href={m.fileURL} target="_blank" rel="noreferrer"><FileText/> {m.fileName||'Resource'}</a>}<div className="card-actions"><button className="btn ghost small" onClick={()=>openModule(m)}><Pencil/> Edit</button><button className="btn danger small" onClick={()=>rmModule(m.id)}><Trash2/> Delete</button></div></article>)}{!mm.length&&<Empty title="No modules found"/>}</div>}
    {tab==='lessons'&&<div className="content-card-grid section-gap">{ll.map(x=><article className="content-card" key={x.id}><span className="chip">{modules.find(m=>m.id===x.moduleId)?.title||x.moduleName||'No module'}</span><h3>{x.title}</h3><p>{x.description||'No description.'}</p><div className="card-meta">{x.fileUrl&&<span className="chip">File</span>}{x.fileId&&<span className="chip">Appwrite</span>}{x.videoUrl&&<span className="chip">Video</span>}</div>{x.fileUrl&&<a className="text-link" href={x.fileUrl} target="_blank" rel="noreferrer"><FileText/> {x.fileName||'Open resource'}</a>}<div className="card-actions"><button className="btn ghost small" onClick={()=>openLesson(x)}><Pencil/> Edit</button><button className="btn danger small" onClick={()=>rmLesson(x.id)}><Trash2/> Delete</button></div></article>)}{!ll.length&&<Empty title="No lessons found"/>}</div>}
    {tab==='resources'&&<section className="panel section-gap"><h2>Learning resources</h2><div className="stack-list">{[...modules.filter(m=>m.fileURL).map(m=>({id:'m'+m.id,title:m.title,url:m.fileURL,type:m.fileId?'Appwrite module file':'Module link'})),...lessons.flatMap(x=>[{id:'f'+x.id,title:x.title,url:x.fileUrl,type:x.fileId?'Appwrite lesson file':'File'},x.videoUrl&&{id:'v'+x.id,title:x.title,url:x.videoUrl,type:'Video'}].filter(r=>r.url))].map(r=><a className="management-row" href={r.url} target="_blank" rel="noreferrer" key={r.id}><span className="management-icon">{r.type==='Video'?<Video/>:<FileText/>}</span><div><strong>{r.title}</strong><p>{r.type}</p></div><ExternalLink/></a>)}</div><div className="design-note inline-note"><Upload/><div><strong>Appwrite Storage active</strong><p>Uploaded files are stored in Appwrite. Firestore keeps only the file metadata and URL used by EqualLearn.</p></div></div></section>}
    <Modal open={!!edit} title={`${edit?.id?'Edit':'Add'} ${edit?.type||''}`} onClose={()=>!uploading&&setEdit(null)}>
      {edit?.type==='module'?<>
        <Field label="Title"><input value={edit.title} onChange={e=>setEdit(v=>({...v,title:e.target.value}))}/></Field><Field label="Description"><textarea rows="4" value={edit.description} onChange={e=>setEdit(v=>({...v,description:e.target.value}))}/></Field><div className="field-grid"><Field label="Order"><input type="number" min="1" value={edit.order} onChange={e=>setEdit(v=>({...v,order:e.target.value}))}/></Field><Field label="Status"><select value={edit.status} onChange={e=>setEdit(v=>({...v,status:e.target.value}))}><option value="active">Active</option><option value="draft">Draft</option><option value="inactive">Inactive</option></select></Field></div>
        <Field label="Upload attachment to Appwrite" hint="PDF, image, document, presentation, or text file · max 20 MB"><input type="file" accept=".jpg,.jpeg,.png,.webp,.pdf,.doc,.docx,.ppt,.pptx,.txt" onChange={fileInfo}/></Field>{edit?.pendingFile&&<Notice>{`Ready to upload: ${edit.pendingFile.name}`}</Notice>}
        <Field label="External resource URL (optional)"><input type="url" value={edit.fileURL} onChange={e=>setEdit(v=>({...v,fileURL:e.target.value,pendingFile:null}))}/></Field><Field label="Resource name"><input value={edit.fileName} onChange={e=>setEdit(v=>({...v,fileName:e.target.value}))}/></Field>
      </>:<>
        <Field label="Module"><select value={edit?.moduleId||''} onChange={e=>setEdit(v=>({...v,moduleId:e.target.value}))}><option value="">Select module</option>{modules.map(m=><option value={m.id} key={m.id}>{m.title}</option>)}</select></Field><Field label="Title"><input value={edit?.title||''} onChange={e=>setEdit(v=>({...v,title:e.target.value}))}/></Field><Field label="Description"><textarea rows="4" value={edit?.description||''} onChange={e=>setEdit(v=>({...v,description:e.target.value}))}/></Field>
        <Field label="Upload lesson attachment to Appwrite" hint="PDF, image, document, presentation, or text file · max 20 MB"><input type="file" accept=".jpg,.jpeg,.png,.webp,.pdf,.doc,.docx,.ppt,.pptx,.txt" onChange={fileInfo}/></Field>{edit?.pendingFile&&<Notice>{`Ready to upload: ${edit.pendingFile.name}`}</Notice>}
        <Field label="External resource URL (optional)"><input type="url" value={edit?.fileUrl||''} onChange={e=>setEdit(v=>({...v,fileUrl:e.target.value,pendingFile:null}))}/></Field><Field label="File name"><input value={edit?.fileName||''} onChange={e=>setEdit(v=>({...v,fileName:e.target.value}))}/></Field><Field label="Video URL"><input type="url" value={edit?.videoUrl||''} onChange={e=>setEdit(v=>({...v,videoUrl:e.target.value}))}/></Field>
      </>}
      <Notice type="error">{msg&&msg!=='Saved successfully.'?msg:''}</Notice><div className="modal-actions"><button className="btn ghost" disabled={uploading} onClick={()=>setEdit(null)}>Cancel</button><button className="btn primary" disabled={uploading} onClick={save}>{uploading?<RefreshCw className="spin"/>:<Save/>} {uploading?'Uploading…':'Save'}</button></div>
    </Modal>
  </AppShell>
}
export function TeacherStudents(){
  const{firebaseUser}=useAuth();const l=useLoad(()=>teacherBundle(firebaseUser.uid),[firebaseUser.uid]);
  const[search,setSearch]=useState(''),[course,setCourse]=useState('all'),[year,setYear]=useState('all'),[selected,setSelected]=useState(null),[msg,setMsg]=useState('');
  if(l.loading)return <AppShell role="teacher"><Loading/></AppShell>;
  const{students,progress,lessons}=l.data||{students:[],progress:[],lessons:[]},courses=[...new Set(students.map(studentCourse).filter(Boolean))],years=YEAR_LEVELS;
  let rows=students.filter(x=>!search||hay(x.fullname,x.studentNumber,x.email,studentSection(x),studentCourse(x),normalizeYearLevel(x.yearLevel)).includes(lower(search)));if(course!=='all')rows=rows.filter(x=>studentCourse(x)===course);if(year!=='all')rows=rows.filter(x=>normalizeYearLevel(x.yearLevel)===year);
  const stats=student=>{const p=progress.filter(x=>x.userId===student.id),avg=p.length?Math.round(p.reduce((a,x)=>a+Number(x.percentage||0),0)/p.length):0,last=Math.max(0,...p.map(x=>timestampMs(x.completedAt)));return{p,avg,last,passed:p.filter(x=>x.result==='passing').length}};
  async function removeStudent(student){if(!confirm(`Delete ${student.fullname||student.email} from EqualLearn? This removes the Firestore profile and saved learning records. The Firebase Authentication credential remains until privileged server-side deletion is configured.`))return;try{await deleteStudentProfile(student.id);setSelected(null);setMsg('Student profile and learning records deleted from EqualLearn.');l.refresh()}catch(e){setMsg(e.message||'Unable to delete this student.') }}
  return <AppShell role="teacher"><Page eyebrow="Students" title="Student profiles" text="Review learners by course, year level, and section, then inspect their profiles and quiz history."/><Notice>{msg}</Notice>
    <div className="toolbar"><div className="searchbox"><Search/><input placeholder="Search name, ID, email, or section…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={course} onChange={e=>setCourse(e.target.value)}><option value="all">All courses</option>{courses.map(x=><option key={x}>{x}</option>)}</select><select value={year} onChange={e=>setYear(e.target.value)}><option value="all">All years</option>{years.map(x=><option key={x}>{x}</option>)}</select></div>
    <section className="panel section-gap"><Table headers={['Student','Course','Year Level','Section','Attempts','Average','Last active']} rows={rows.map(student=>{const x=stats(student);return{key:student.id,cells:[<button className="table-name-button" onClick={()=>setSelected(student)}><strong>{student.fullname}</strong><small>{student.studentNumber||student.email}</small></button>,studentCourse(student),normalizeYearLevel(student.yearLevel)||'—',sectionOf(student),x.p.length,pct(x.avg),x.last?formatWhen(x.last):'—']}})} empty="No students match these filters."/></section>
    <Modal open={!!selected} title="Student profile" onClose={()=>setSelected(null)} wide>{selected&&(()=>{const x=stats(selected);return <div className="profile-detail-modal"><ProfileView person={selected} role="student" actions={<button className="btn danger-soft" onClick={()=>removeStudent(selected)}><Trash2/> Delete student</button>}/><div className="stats-grid compact section-gap"><Stat label="Attempts" value={x.p.length}/><Stat label="Average" value={pct(x.avg)}/><Stat label="Passed" value={x.passed}/></div><section className="profile-history section-gap"><div className="section-row"><div><span className="mini-label">LEARNING HISTORY</span><h3>Quiz activity</h3></div></div><div className="stack-list">{x.p.map(p=><div className="activity-row" key={p.id}><span className="activity-dot"/><div><strong>{lessons.find(ls=>ls.id===p.lessonId)?.title||'Lesson'}</strong><p>{p.score}/{p.total} · {pct(p.percentage)}</p></div><small>{formatWhen(p.completedAt)}</small></div>)}{!x.p.length&&<Empty title="No quiz history"/>}</div></section></div>})()}</Modal>
  </AppShell>
}

export function TeacherQuizBuilder(){
  const{firebaseUser}=useAuth();
  const l=useLoad(()=>teacherBundle(firebaseUser.uid),[firebaseUser.uid]);
  const[search,setSearch]=useState(''),[lesson,setLesson]=useState('all'),[edit,setEdit]=useState(null),[msg,setMsg]=useState('');
  const[sEdit,setSEdit]=useState(null),[sMsg,setSMsg]=useState('');
  if(l.loading)return <AppShell role="teacher"><Loading/></AppShell>;
  const{lessons,questions,quizzes}=l.data||{lessons:[],questions:[],quizzes:[]};
  let rows=questions.filter(q=>!search||hay(q.question,q.choiceA,q.choiceB,q.choiceC,q.choiceD).includes(lower(search)));
  if(lesson!=='all')rows=rows.filter(q=>q.lessonId===lesson);
  const open=q=>setEdit({id:q?.id||'',lessonId:q?.lessonId||lessons[0]?.id||'',question:q?.question||'',choiceA:q?.choiceA||'',choiceB:q?.choiceB||'',choiceC:q?.choiceC||'',choiceD:q?.choiceD||'',correctAnswer:q?.correctAnswer||'A'});
  async function save(){try{if(!edit.lessonId||!edit.question.trim()||!edit.choiceA.trim()||!edit.choiceB.trim()||!edit.choiceC.trim()||!edit.choiceD.trim())throw new Error('Complete the lesson, question, and all four choices.');await saveQuestion({...edit,uid:firebaseUser.uid});setEdit(null);setMsg('');l.refresh()}catch(e){setMsg(e.message)}}
  async function rm(id){if(confirm('Delete this question?')){await deleteQuestion(id);l.refresh()}}
  function editSettings(x){if(!x||!x.id)return;setSMsg('');setSEdit({lessonId:x.id,title:x.title||'',...quizSettingsFor(quizzes,x.id)})}
  async function saveSettings(){try{await saveQuizSettings(sEdit);setSEdit(null);setSMsg('');l.refresh()}catch(e){setSMsg(e?.message||'Unable to save quiz settings.')}}
  return <AppShell role="teacher">
    <Page eyebrow="Quiz Builder" title="Build lesson assessments" text="Create the same A–D questions used by the student quiz, and set the rules for each quiz." action={<div className="card-actions"><button className="btn ghost" onClick={()=>editSettings(lessons[0])} disabled={!lessons.length}><ClipboardCheck/> Quiz settings</button><button className="btn primary" onClick={()=>open()}><Plus/> Add question</button></div>}/>
    <div className="toolbar"><div className="searchbox"><Search/><input placeholder="Search questions…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={lesson} onChange={e=>setLesson(e.target.value)}><option value="all">All lessons</option>{lessons.map(x=><option value={x.id} key={x.id}>{x.title}</option>)}</select></div>
    <section className="panel section-gap"><div className="section-row"><div><span className="mini-label">QUIZ RULES</span><h2>Per-lesson settings</h2></div><small>Time limit, attempts, and passing score apply to the student quiz.</small></div><div className="stack-list">{lessons.map(x=>{const s=quizSettingsFor(quizzes,x.id),count=questions.filter(q=>q.lessonId===x.id).length;return <article className="management-row" key={x.id}><span className="management-icon"><ClipboardCheck/></span><div><strong>{x.title}</strong><p>{count} question{count===1?'':'s'} · {s.timeLimitMinutes?`${s.timeLimitMinutes} min limit`:'No time limit'} · {s.attemptsAllowed?`${s.attemptsAllowed} attempt${s.attemptsAllowed===1?'':'s'}`:'Unlimited attempts'} · pass {s.passingScore}%{s.shuffleQuestions?' · shuffled':''}</p></div><div className="row-actions"><button className="btn ghost small" onClick={()=>editSettings(x)}><Pencil/> Settings</button></div></article>})}{!lessons.length&&<Empty title="Add a lesson before configuring a quiz"/>}</div></section>
    <section className="panel section-gap"><h2>Questions</h2><div className="stack-list">{rows.map((q,i)=><article className="question-row" key={q.id}><span className="question-number">{i+1}</span><div><strong>{q.question}</strong><p>{lessons.find(x=>x.id===q.lessonId)?.title||'Unknown lesson'} · Correct: {q.correctAnswer}</p><div className="choice-preview"><span>A. {q.choiceA}</span><span>B. {q.choiceB}</span><span>C. {q.choiceC}</span><span>D. {q.choiceD}</span></div></div><div className="row-actions"><button className="icon-btn" onClick={()=>open(q)}><Pencil/></button><button className="icon-btn danger-soft" onClick={()=>rm(q.id)}><Trash2/></button></div></article>)}{!rows.length&&<Empty title="No questions found"/>}</div></section>
    <Modal open={!!edit} title={`${edit?.id?'Edit':'Add'} question`} onClose={()=>setEdit(null)} wide><Field label="Lesson"><select value={edit?.lessonId||''} onChange={e=>setEdit(v=>({...v,lessonId:e.target.value}))}>{lessons.map(x=><option value={x.id} key={x.id}>{x.title}</option>)}</select></Field><Field label="Question"><textarea rows="3" value={edit?.question||''} onChange={e=>setEdit(v=>({...v,question:e.target.value}))}/></Field>{['A','B','C','D'].map(k=><Field label={`Choice ${k}`} key={k}><input value={edit?.[`choice${k}`]||''} onChange={e=>setEdit(v=>({...v,[`choice${k}`]:e.target.value}))}/></Field>)}<Field label="Correct answer"><div className="segmented-options">{['A','B','C','D'].map(k=><button type="button" className={edit?.correctAnswer===k?'active':''} onClick={()=>setEdit(v=>({...v,correctAnswer:k}))} key={k}>{k}</button>)}</div></Field><Notice type="error">{msg}</Notice><div className="modal-actions"><button className="btn ghost" onClick={()=>setEdit(null)}>Cancel</button><button className="btn primary" onClick={save}><Save/> Save question</button></div></Modal>
    <Modal open={!!sEdit} title="Quiz settings" onClose={()=>setSEdit(null)}>
      <Field label="Lesson"><input value={sEdit?.title||''} readOnly/></Field>
      <div className="field-grid">
        <Field label="Time limit (minutes)" hint="0 = no time limit"><input type="number" min="0" value={sEdit?.timeLimitMinutes??0} onChange={e=>setSEdit(v=>({...v,timeLimitMinutes:e.target.value}))}/></Field>
        <Field label="Attempts allowed" hint="0 = unlimited"><input type="number" min="0" value={sEdit?.attemptsAllowed??0} onChange={e=>setSEdit(v=>({...v,attemptsAllowed:e.target.value}))}/></Field>
        <Field label="Passing score (%)"><input type="number" min="1" max="100" value={sEdit?.passingScore??75} onChange={e=>setSEdit(v=>({...v,passingScore:e.target.value}))}/></Field>
      </div>
      <label className="check-row"><input type="checkbox" checked={!!sEdit?.shuffleQuestions} onChange={e=>setSEdit(v=>({...v,shuffleQuestions:e.target.checked}))}/> Shuffle question order for each attempt</label>
      <label className="check-row"><input type="checkbox" checked={sEdit?.showAnswersAfter!==false} onChange={e=>setSEdit(v=>({...v,showAnswersAfter:e.target.checked}))}/> Show correct answers after submitting</label>
      <Notice type="error">{sMsg}</Notice>
      <div className="modal-actions"><button className="btn ghost" onClick={()=>setSEdit(null)}>Cancel</button><button className="btn primary" onClick={saveSettings}><Save/> Save settings</button></div>
    </Modal>
  </AppShell>
}

export function TeacherAnalytics(){const{firebaseUser}=useAuth();const l=useLoad(()=>teacherBundle(firebaseUser.uid),[firebaseUser.uid]);if(l.loading)return <AppShell role="teacher"><Loading/></AppShell>;const{students,progress,questions}=l.data||{students:[],progress:[],questions:[]},avg=progress.length?Math.round(progress.reduce((s,p)=>s+Number(p.percentage||0),0)/progress.length):0,active=new Set(progress.filter(p=>timestampMs(p.completedAt)>Date.now()-7*86400000).map(p=>p.userId)).size,rows=students.map(s=>{const p=progress.filter(x=>x.userId===s.id),a=p.length?Math.round(p.reduce((z,x)=>z+Number(x.percentage||0),0)/p.length):0;return{...s,attempts:p.length,average:a,passed:p.filter(x=>x.result==='passing').length}}).sort((a,b)=>b.average-a.average);return <AppShell role="teacher"><Page eyebrow="Analytics" title="Class engagement" text="Live assessment figures calculated from assigned students."/><div className="stats-grid"><Stat label="Assigned students" value={students.length} Icon={Users}/><Stat label="Active this week" value={active} Icon={Activity}/><Stat label="Attempts" value={progress.length} Icon={ClipboardCheck}/><Stat label="Average" value={pct(avg)} Icon={BarChart3}/></div><section className="panel section-gap"><Table headers={['Student','Course','Year Level','Section','Attempts','Passed','Average']} rows={rows.map(s=>({key:s.id,cells:[<><strong>{s.fullname}</strong><small>{s.studentNumber}</small></>,studentCourse(s),normalizeYearLevel(s.yearLevel)||'—',sectionOf(s),s.attempts,s.passed,pct(s.average)]}))} empty="No assigned student activity yet."/></section><section className="panel section-gap"><h2>Assessment coverage</h2><p>{questions.length} questions across {new Set(questions.map(q=>q.lessonId)).size} lessons.</p></section></AppShell>}

export function TeacherProfile(){
  const{firebaseUser,profile,refreshProfile}=useAuth();
  const initial=nameParts(profile);
  const[f,setF]=useState({...initial,department:profile?.department||'',title:profile?.title||'',phone:profile?.phone||'',bio:profile?.bio||''}),[msg,setMsg]=useState('');
  const set=(k,v)=>setF(x=>({...x,[k]:v}));const setName=v=>setF(x=>({...x,...v}));async function save(e){e.preventDefault();const firstName=normalizePersonName(f.firstName),middleInitial=normalizeMiddleInitial(f.middleInitial),lastName=normalizePersonName(f.lastName);if(!firstName||!lastName){setMsg('Enter your first and last name.');return;}const fullname=fullNameFromParts({firstName,middleInitial,lastName});await saveProfile(firebaseUser.uid,{firstName,middleInitial,lastName,fullname,department:f.department,title:f.title,phone:f.phone,bio:f.bio});await refreshProfile();setMsg('Teacher profile updated.');}
  const preview={...profile,...f,fullname:fullNameFromParts(f)||profile?.fullname};
  return <AppShell role="teacher"><Page eyebrow="Profile" title="Teacher profile" text="Maintain a clear professional profile that students and administrators can understand."/>
    <div className="profile-layout refined-profile-layout"><section className="panel profile-summary refined-profile-summary"><ProfileAvatar size="xl" editable/><ProfileView person={preview} role="teacher" section={f.department||'Faculty'}/></section>
      <form className="panel form-panel profile-edit-panel" onSubmit={save}><div className="section-row"><div><span className="mini-label">PROFILE DETAILS</span><h2>Edit information</h2></div><small>Profile pictures are stored in Appwrite and appear across EqualLearn.</small></div><NameFields value={f} onChange={setName} required idPrefix="teacher"/><Field label="Email"><input value={profile?.email||''} readOnly/></Field><div className="field-grid"><Field label="Department / Section"><input value={f.department} onChange={e=>set('department',e.target.value)}/></Field><Field label="Professional title"><input value={f.title} onChange={e=>set('title',e.target.value)}/></Field><Field label="Phone"><input value={f.phone} onChange={e=>set('phone',e.target.value)} placeholder="Optional contact number"/></Field></div><Field label="Bio"><textarea rows="5" value={f.bio} onChange={e=>set('bio',e.target.value)} placeholder="Short professional introduction."/></Field><Notice type="success">{msg}</Notice><button className="btn primary"><Save/> Save profile</button></form>
    </div>
  </AppShell>
}

async function adminBundle(){const[users,modules,lessons,questions,progress,assignments,classGroups]=await Promise.all([getUsers(),getModules(),getLessons(),getQuestions(),getProgress(),getAssignments(),getClassGroups()]);return{users,modules,lessons,questions,progress,assignments,classGroups}}

export function AdminDashboard(){const l=useLoad(adminBundle,[]);if(l.loading)return <AppShell role="admin"><Loading/></AppShell>;if(l.error)return <AppShell role="admin"><Failure message={l.error} retry={l.refresh}/></AppShell>;const{users,modules,lessons,progress,assignments}=l.data,students=users.filter(x=>lower(x.role)==='student'),teachers=users.filter(x=>lower(x.role)==='teacher'),avg=progress.length?Math.round(progress.reduce((s,p)=>s+Number(p.percentage||0),0)/progress.length):0,recent=[...progress].sort((a,b)=>timestampMs(b.completedAt)-timestampMs(a.completedAt)).slice(0,6);return <AppShell role="admin"><Page eyebrow="Administration" title="EqualLearn control center" text="Live system oversight using the existing EqualLearn collections."/><div className="stats-grid"><Stat label="Students" value={students.length} detail={`${students.filter(x=>lower(x.status||'active')!=='inactive').length} active`} Icon={Users}/><Stat label="Teachers" value={teachers.length} detail={`${assignments.filter(x=>lower(x.status||'active')==='active').length} active designations`} Icon={GraduationCap}/><Stat label="Modules / lessons" value={`${modules.length} / ${lessons.length}`} Icon={BookOpen}/><Stat label="Average score" value={pct(avg)} detail={`${progress.length} assessment records`} Icon={BarChart3}/></div><div className="dashboard-grid section-gap"><section className="panel"><span className="mini-label">MANAGEMENT</span><h2>Administration tools</h2><div className="management-list">{[[Users,'Students','Search registered student profiles.','/admin/users'],[GraduationCap,'Teachers','Create and maintain teacher accounts.','/admin/teachers'],[Layers3,'Teacher Designations','Assign teachers to sections and manage designation status.','/admin/classes'],[BarChart3,'Reports','Review learning performance.','/admin/reports']].map(([I,t,d,to])=><Link className="management-row" to={to} key={t}><span className="management-icon"><I/></span><div><strong>{t}</strong><p>{d}</p></div><ChevronRight/></Link>)}</div></section><section className="panel"><span className="mini-label">RECENT ASSESSMENTS</span><h2>Latest results</h2><div className="stack-list compact">{recent.map(p=>{const s=students.find(x=>x.id===p.userId),lesson=lessons.find(x=>x.id===p.lessonId);return <div className="activity-row" key={p.id}><span className="activity-dot"/><div><strong>{s?.fullname||'Student'}</strong><p>{lesson?.title||'Lesson'} · {pct(p.percentage)}</p></div><small>{formatWhen(p.completedAt)}</small></div>})}{!recent.length&&<Empty title="No assessment activity yet"/>}</div></section></div></AppShell>}

export function AdminUsers(){
  const l=useLoad(adminBundle,[]);const[search,setSearch]=useState(''),[course,setCourse]=useState('all'),[year,setYear]=useState('all'),[selected,setSelected]=useState(null),[msg,setMsg]=useState('');
  if(l.loading)return <AppShell role="admin"><Loading/></AppShell>;
  const students=(l.data?.users||[]).filter(x=>lower(x.role)==='student'),courses=[...new Set(students.map(studentCourse).filter(Boolean))],years=YEAR_LEVELS;let rows=students.filter(x=>!search||hay(x.fullname,x.studentNumber,x.email,studentCourse(x),normalizeYearLevel(x.yearLevel),studentSection(x)).includes(lower(search)));if(course!=='all')rows=rows.filter(x=>studentCourse(x)===course);if(year!=='all')rows=rows.filter(x=>normalizeYearLevel(x.yearLevel)===year);
  async function removeStudent(student){if(!confirm(`Delete ${student.fullname||student.email} from EqualLearn? This removes the Firestore profile and saved learning records. The Firebase Authentication credential remains until privileged server-side deletion is configured.`))return;try{await deleteStudentProfile(student.id);setSelected(null);setMsg('Student profile and learning records deleted from EqualLearn.');l.refresh()}catch(e){setMsg(e.message||'Unable to delete this student.') }}
  return <AppShell role="admin"><Page eyebrow="Students" title="Registered students" text="Manage student profiles by section, contact information, course, and status."/><Notice>{msg}</Notice><div className="toolbar"><div className="searchbox"><Search/><input placeholder="Search students…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={course} onChange={e=>setCourse(e.target.value)}><option value="all">All courses</option>{courses.map(x=><option key={x}>{x}</option>)}</select><select value={year} onChange={e=>setYear(e.target.value)}><option value="all">All years</option>{years.map(x=><option key={x}>{x}</option>)}</select></div><section className="panel section-gap"><Table headers={['Student','Student ID','Course','Year Level','Section','Email','Status','Actions']} rows={rows.map(student=>({key:student.id,cells:[<button className="table-name-button" onClick={()=>setSelected(student)}><strong>{student.fullname||'Student'}</strong><small>View profile</small></button>,student.studentNumber||'—',studentCourse(student),normalizeYearLevel(student.yearLevel)||'—',sectionOf(student),student.email||'—',<span className={`status-pill ${lower(student.status||'active')}`}>{student.status||'active'}</span>,<div className="row-actions"><button className="btn ghost small" onClick={()=>setSelected(student)}>View</button><button className="icon-btn danger-soft" onClick={()=>removeStudent(student)} title="Delete student"><Trash2/></button></div>]}))} empty="No registered students match these filters."/></section><Modal open={!!selected} title="Student profile" onClose={()=>setSelected(null)} wide>{selected&&<ProfileView person={selected} role="student" actions={<button className="btn danger-soft" onClick={()=>removeStudent(selected)}><Trash2/> Delete student</button>}/>}</Modal></AppShell>
}

export function AdminTeachers(){
  const l=useLoad(adminBundle,[]);const[search,setSearch]=useState(''),[edit,setEdit]=useState(null),[selected,setSelected]=useState(null),[msg,setMsg]=useState('');if(l.loading)return <AppShell role="admin"><Loading/></AppShell>;
  const rows=(l.data?.users||[]).filter(x=>lower(x.role)==='teacher').filter(x=>!search||hay(x.fullname,x.email,x.department,x.phone).includes(lower(search)));
  const open=t=>setEdit(t?{mode:'edit',id:t.id,...nameParts(t),email:t.email||'',department:t.department||'',status:t.status||'active',phone:t.phone||'',bio:t.bio||'',password:''}:{mode:'add',firstName:'',middleInitial:'',lastName:'',email:'',department:'',status:'active',phone:'',bio:'',password:''});
  async function save(){try{const firstName=normalizePersonName(edit.firstName),middleInitial=normalizeMiddleInitial(edit.middleInitial),lastName=normalizePersonName(edit.lastName);if(!firstName||!lastName)throw new Error('First name and last name are required.');if(!edit.email.trim())throw new Error('Email is required.');const fullname=fullNameFromParts({firstName,middleInitial,lastName});if(edit.mode==='add'){if(edit.password.length<6)throw new Error('Password must be at least 6 characters.');await createTeacherAccount({...edit,firstName,middleInitial,lastName,fullname})}else await updateTeacher(edit.id,{firstName,middleInitial,lastName,fullname,department:edit.department.trim(),status:edit.status,phone:edit.phone.trim(),bio:edit.bio.trim()});setEdit(null);setMsg('');l.refresh()}catch(e){setMsg(e.message)}}
  async function rm(t){if(confirm(`Remove ${t.fullname||t.email}'s Firestore profile? The Firebase Auth record is not deleted.`)){await deleteTeacherProfile(t.id);setSelected(null);l.refresh()}}
  return <AppShell role="admin"><Page eyebrow="Teachers" title="Manage teachers" text="Create teacher accounts, review complete profiles, and maintain professional contact information." action={<button className="btn primary" onClick={()=>open()}><Plus/> Add teacher</button>}/><div className="toolbar"><div className="searchbox"><Search/><input placeholder="Search teachers…" value={search} onChange={e=>setSearch(e.target.value)}/></div></div><section className="panel section-gap"><Table headers={['Teacher','Department / Section','Email','Phone','Status','Actions']} rows={rows.map(t=>({key:t.id,cells:[<button className="table-name-button" onClick={()=>setSelected(t)}><strong>{t.fullname||'Teacher'}</strong><small>View profile</small></button>,t.department||'—',t.email||'—',t.phone||'—',<span className={`status-pill ${lower(t.status||'active')}`}>{t.status||'active'}</span>,<div className="row-actions"><button className="btn ghost small" onClick={()=>setSelected(t)}>View</button><button className="icon-btn" onClick={()=>open(t)}><Pencil/></button><button className="icon-btn danger-soft" onClick={()=>rm(t)}><Trash2/></button></div>]}))} empty="No teacher accounts found."/></section>
    <Modal open={!!selected} title="Teacher profile" onClose={()=>setSelected(null)} wide>{selected&&<ProfileView person={selected} role="teacher" section={selected.department||'Faculty'} actions={<><button className="btn ghost" onClick={()=>{open(selected);setSelected(null)}}><Pencil/> Edit profile</button><button className="btn danger-soft" onClick={()=>rm(selected)}><Trash2/> Remove teacher</button></>}/>}</Modal>
    <Modal open={!!edit} title={edit?.mode==='add'?'Add teacher':'Edit teacher'} onClose={()=>setEdit(null)}><NameFields value={edit} onChange={v=>setEdit(x=>({...x,...v}))} required idPrefix="admin-teacher"/><Field label="Email"><input type="email" readOnly={edit?.mode==='edit'} value={edit?.email||''} onChange={e=>setEdit(v=>({...v,email:e.target.value}))}/></Field>{edit?.mode==='add'&&<Field label="Temporary password"><PasswordInput value={edit?.password||''} onChange={e=>setEdit(v=>({...v,password:e.target.value}))} autoComplete="new-password"/></Field>}<Field label="Department / Section"><input value={edit?.department||''} onChange={e=>setEdit(v=>({...v,department:e.target.value}))}/></Field><Field label="Phone"><input value={edit?.phone||''} onChange={e=>setEdit(v=>({...v,phone:e.target.value}))}/></Field><Field label="Bio"><textarea rows="4" value={edit?.bio||''} onChange={e=>setEdit(v=>({...v,bio:e.target.value}))}/></Field><Field label="Status"><select value={edit?.status||'active'} onChange={e=>setEdit(v=>({...v,status:e.target.value}))}><option value="active">Active</option><option value="inactive">Inactive</option></select></Field><Notice type="error">{msg}</Notice><div className="modal-actions"><button className="btn ghost" onClick={()=>setEdit(null)}>Cancel</button><button className="btn primary" onClick={save}><Save/> Save teacher</button></div></Modal>
  </AppShell>
}

export function AdminClasses(){
  const l=useLoad(adminBundle,[]);
  const[f,setF]=useState({classGroupId:'',yearLevel:'',teacherId:''}),[msg,setMsg]=useState('');
  if(l.loading)return <AppShell role="admin"><Loading/></AppShell>;
  const{classGroups,assignments,users}=l.data||{classGroups:[],assignments:[],users:[]};
  const teachers=users.filter(x=>lower(x.role)==='teacher'&&lower(x.status||'active')!=='inactive');
  const group=classGroups.find(x=>x.id===f.classGroupId);
  const years=group?.yearLevels?.length?group.yearLevels.map(normalizeYearLevel).filter(y=>YEAR_LEVELS.includes(y)):YEAR_LEVELS;
  const set=(k,v)=>setF(x=>({...x,[k]:v}));
  async function generate(){try{const count=await generateClassGroupsFromStudents();setMsg(`${count} sections generated/refreshed.`);l.refresh()}catch(e){setMsg(e.message)}}
  async function assign(e){e.preventDefault();try{if(!f.classGroupId||!f.yearLevel||!f.teacherId)throw new Error('Choose a section, year, and teacher.');await assignTeacher(f);setMsg('Teacher designation saved and activated.');l.refresh()}catch(e){setMsg(e.message)}}
  async function activate(id){try{await activateAssignment(id);setMsg('Teacher designation activated.');l.refresh()}catch(e){setMsg(e.message)}}
  async function deactivate(id){if(confirm('Deactivate this teacher designation? Students will stop using it until it is activated again.')){try{await deactivateAssignment(id);setMsg('Teacher designation deactivated.');l.refresh()}catch(e){setMsg(e.message)}}}
  async function remove(id){if(confirm('Delete this teacher designation? It will move to the recoverable deleted state and can be retrieved later.')){try{await deleteAssignment(id);setMsg('Teacher designation moved to deleted.');l.refresh()}catch(e){setMsg(e.message)}}}
  async function retrieve(id){try{await retrieveAssignment(id);setMsg('Teacher designation retrieved as inactive. Activate it when you are ready to use it again.');l.refresh()}catch(e){setMsg(e.message)}}
  const actions=a=>{const status=lower(a.status||'active');if(status==='deleted')return <div className="row-actions"><button className="btn ghost small" onClick={()=>retrieve(a.id)}><RefreshCw/> Retrieve</button></div>;if(status==='inactive')return <div className="row-actions"><button className="btn ghost small" onClick={()=>activate(a.id)}><Check/> Activate</button><button className="btn danger-soft small" onClick={()=>remove(a.id)}><Trash2/> Delete</button></div>;return <div className="row-actions"><button className="btn ghost small" onClick={()=>deactivate(a.id)}>Deactivate</button><button className="btn danger-soft small" onClick={()=>remove(a.id)}><Trash2/> Delete</button></div>};
  return <AppShell role="admin"><Page eyebrow="Teacher Designation" title="Teacher Designations" text="Assign teachers to student sections and manage each designation through active, inactive, and recoverable deleted states." action={<button className="btn ghost" onClick={generate}><RefreshCw/> Refresh sections</button>}/><Notice>{msg}</Notice><div className="form-layout section-gap"><form className="panel" onSubmit={assign}><h2>Create designation</h2><Field label="Section"><select value={f.classGroupId} onChange={e=>{set('classGroupId',e.target.value);set('yearLevel','')}}><option value="">Select section</option>{classGroups.map(g=><option value={g.id} key={g.id}>Section {g.section||'—'} · {g.studentCount||0} students</option>)}</select></Field><Field label="Year level"><select value={f.yearLevel} onChange={e=>set('yearLevel',e.target.value)}><option value="">Select year</option>{years.map(y=><option key={y}>{y}</option>)}</select></Field><Field label="Teacher"><select value={f.teacherId} onChange={e=>set('teacherId',e.target.value)}><option value="">Select teacher</option>{teachers.map(t=><option value={t.id} key={t.id}>{t.fullname||t.email}</option>)}</select></Field><button className="btn primary">Save designation</button></form><section className="panel"><h2>Student sections</h2><div className="stack-list compact">{classGroups.map(g=><div className="activity-row" key={g.id}><span className="activity-dot"/><div><strong>Section {g.section||'—'}</strong><p>Course {g.course||'BSIT'} · Years {(g.yearLevels||[]).map(normalizeYearLevel).filter(Boolean).join(', ')||'—'}</p></div><small>{g.studentCount||0} students</small></div>)}{!classGroups.length&&<Empty title="No sections yet"/>}</div></section></div><section className="panel section-gap"><div className="section-row"><div><span className="mini-label">DESIGNATION RECORDS</span><h2>Teacher Designations</h2></div><small>Deleted records remain recoverable.</small></div><Table headers={['Course','Year Level','Section','Teacher','Status','Actions']} rows={assignments.map(a=>({key:a.id,cells:[String(a.course||'BSIT').toUpperCase(),normalizeYearLevel(a.yearLevel)||'—',`Section ${normalizeSection(a.section||a.cohort)||'—'}`,a.teacherName||'—',<span className={`status-pill ${lower(a.status||'active')}`}>{a.status||'active'}</span>,actions(a)]}))} empty="No teacher designations yet."/></section></AppShell>
}

export function AdminReports(){const l=useLoad(adminBundle,[]);const[search,setSearch]=useState(''),[course,setCourse]=useState('all'),[year,setYear]=useState('all'),[result,setResult]=useState('all'),[status,setStatus]=useState('all');if(l.loading)return <AppShell role="admin"><Loading/></AppShell>;const all=reportRows(l.data.users,l.data.progress),courses=[...new Set(all.map(x=>studentCourse(x)).filter(Boolean))],years=YEAR_LEVELS;let rows=all.filter(x=>!search||hay(x.fullname,x.studentNumber,x.email).includes(lower(search)));if(course!=='all')rows=rows.filter(x=>studentCourse(x)===course);if(year!=='all')rows=rows.filter(x=>normalizeYearLevel(x.yearLevel)===year);if(result!=='all')rows=rows.filter(x=>x.result===result);if(status!=='all')rows=rows.filter(x=>lower(x.schoolStatus)===status);const avg=rows.length?Math.round(rows.reduce((s,x)=>s+x.grade,0)/rows.length):0,passing=rows.filter(x=>x.result==='passing').length;function csv(){const h=['Full name','Student ID','Email','Course','Year Level','Section','Grade','Result','Status'],lines=[h,...rows.map(x=>[x.fullname,x.studentNumber,x.email,studentCourse(x),normalizeYearLevel(x.yearLevel),sectionOf(x),x.grade,x.result,x.schoolStatus])].map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','));const b=new Blob([lines.join('\n')],{type:'text/csv'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='equallearn-student-reports.csv';a.click();URL.revokeObjectURL(u)}return <AppShell role="admin"><Page eyebrow="Reports" title="Student performance reports" text="Grades match the old branch logic: average of each student's saved quiz percentages." action={<button className="btn ghost" onClick={csv}><Download/> Export CSV</button>}/><div className="stats-grid"><Stat label="Students shown" value={rows.length}/><Stat label="Passing" value={passing}/><Stat label="Average" value={pct(avg)}/></div><div className="toolbar section-gap"><div className="searchbox"><Search/><input placeholder="Search student…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={course} onChange={e=>setCourse(e.target.value)}><option value="all">All courses</option>{courses.map(x=><option key={x}>{x}</option>)}</select><select value={year} onChange={e=>setYear(e.target.value)}><option value="all">All years</option>{years.map(x=><option key={x}>{x}</option>)}</select><select value={result} onChange={e=>setResult(e.target.value)}><option value="all">All results</option><option value="passing">Passing</option><option value="failing">Failing</option></select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><section className="panel section-gap"><Table headers={['Student','ID','Course','Year Level','Section','Grade','Result','Status']} rows={rows.map(x=>({key:x.id,cells:[<strong>{x.fullname}</strong>,x.studentNumber||'—',studentCourse(x),normalizeYearLevel(x.yearLevel)||'—',sectionOf(x),pct(x.grade),<span className={`status-pill ${x.result}`}>{x.result}</span>,x.schoolStatus]}))} empty="No report records match these filters."/></section></AppShell>}

export function LiveSettings({role}){const{firebaseUser,profile,refreshProfile}=useAuth();const[name,setName]=useState(nameParts(profile)),[current,setCurrent]=useState(''),[next,setNext]=useState(''),[confirmNext,setConfirmNext]=useState(''),[msg,setMsg]=useState(''),[security,setSecurity]=useState('');async function save(){const firstName=normalizePersonName(name.firstName),middleInitial=normalizeMiddleInitial(name.middleInitial),lastName=normalizePersonName(name.lastName);if(!firstName||!lastName){setMsg('Enter your first and last name.');return}const fullname=fullNameFromParts({firstName,middleInitial,lastName});await saveProfile(firebaseUser.uid,{firstName,middleInitial,lastName,fullname});await refreshProfile();setMsg('Account information saved.')}async function reset(){try{await sendPasswordResetEmail(auth,firebaseUser.email);setSecurity('Password reset email sent.')}catch(e){setSecurity(e.message)}}async function change(){if(!current||!next||!confirmNext){setSecurity('Complete all password fields.');return}if(next.length<6){setSecurity('New password must contain at least 6 characters.');return}if(next!==confirmNext){setSecurity('New passwords do not match.');return}try{await reauthenticateWithCredential(firebaseUser,EmailAuthProvider.credential(firebaseUser.email,current));await updatePassword(firebaseUser,next);setCurrent('');setNext('');setConfirmNext('');setSecurity('Password changed successfully.')}catch(e){setSecurity(e.code==='auth/invalid-credential'?'Current password is incorrect.':e.message)}}return <AppShell role={role}><Page eyebrow="Settings" title={`${cap(role)} settings`} text="Appearance, account information, profile picture, and password security."/><div className="settings-grid"><section className="panel"><h2>Appearance</h2><ThemePicker/></section><section className="panel"><h2>Profile picture</h2><p className="panel-intro">Initials remain the fallback. Profile pictures are uploaded to Appwrite Storage and shared across web and mobile.</p><ProfileAvatar size="xl" editable/></section><section className="panel"><h2>Account information</h2><NameFields value={name} onChange={v=>setName(x=>({...x,...v}))} required idPrefix="settings"/><Field label="Email"><input value={firebaseUser.email||''} readOnly/></Field><Field label="Role"><input value={role} readOnly/></Field><Notice type="success">{msg}</Notice><button className="btn primary" onClick={save}><Save/> Save changes</button></section><section className="panel"><h2>Security</h2><Field label="Current password"><PasswordInput value={current} onChange={e=>setCurrent(e.target.value)} autoComplete="current-password"/></Field><Field label="New password"><PasswordInput value={next} onChange={e=>setNext(e.target.value)} autoComplete="new-password"/></Field><Field label="Confirm password"><PasswordInput value={confirmNext} onChange={e=>setConfirmNext(e.target.value)} autoComplete="new-password"/></Field><Notice>{security}</Notice><div className="card-actions"><button className="btn primary" onClick={change}>Change password</button><button className="btn ghost" onClick={reset}>Email reset link</button></div></section></div></AppShell>}

export function TeacherDeadlines(){
  const{firebaseUser}=useAuth();
  const l=useLoad(async()=>{const t=await teacherBundle(firebaseUser.uid);const[d,o]=await Promise.all([getDeadlines(),getDeadlineOverrides()]);return{...t,deadlines:d,overrides:o}},[firebaseUser.uid]);
  const[classEdit,setClassEdit]=useState(null),[overrideEdit,setOverrideEdit]=useState(null),[msg,setMsg]=useState('');
  if(l.loading)return <AppShell role="teacher"><Loading/></AppShell>;
  const{lessons,students,deadlines,overrides}=l.data||{lessons:[],students:[],deadlines:[],overrides:[]};
  const classDue=lessonId=>(deadlines||[]).find(d=>d.lessonId===lessonId||d.id===lessonId);
  async function saveClass(){try{if(!classEdit.lessonId||!classEdit.dueAt)throw new Error('Choose a lesson and a due date.');const lesson=lessons.find(x=>x.id===classEdit.lessonId);await saveClassDeadline({lessonId:classEdit.lessonId,moduleId:lesson?.moduleId||'',lessonTitle:lesson?.title||'',dueAt:classEdit.dueAt,uid:firebaseUser.uid});setClassEdit(null);setMsg('Class deadline saved for every student.');l.refresh()}catch(e){setMsg(e?.message||'Unable to save the deadline.')}}
  async function removeClass(lessonId){if(!confirm('Remove the class deadline for this lesson?'))return;try{await clearClassDeadline(lessonId);setMsg('Class deadline removed.');l.refresh()}catch(e){setMsg(e?.message||'Unable to remove the deadline.')}}
  async function saveOverride(){try{if(!overrideEdit?.studentId||!overrideEdit?.lessonId||!overrideEdit.dueAt)throw new Error('Choose a student, a lesson, and a due date.');const lesson=lessons.find(x=>x.id===overrideEdit.lessonId),student=students.find(x=>x.id===overrideEdit.studentId);await saveDeadlineOverride({lessonId:overrideEdit.lessonId,studentId:overrideEdit.studentId,studentName:student?.fullname||student?.email||'',lessonTitle:lesson?.title||'',dueAt:overrideEdit.dueAt,reason:overrideEdit.reason,uid:firebaseUser.uid});setOverrideEdit(null);setMsg('Personal deadline saved.');l.refresh()}catch(e){setMsg(e?.message||'Unable to save the adjustment.')}}
  async function removeOverride(id){if(!confirm('Remove this personal deadline?'))return;try{await deleteDeadlineOverride(id);setMsg('Personal deadline removed.');l.refresh()}catch(e){setMsg(e?.message||'Unable to remove the adjustment.')}}
  const blankOverride=()=>({lessonId:lessons[0]?.id||'',studentId:students[0]?.id||'',dueAt:'',reason:''});
  return <AppShell role="teacher">
    <Page eyebrow="Deadlines" title="Due dates" text="Set one deadline for the whole class, or move it for a single student."/>
    <Notice type={msg.includes('Unable')?'error':'success'}>{msg}</Notice>
    <section className="panel"><div className="section-row"><div><span className="mini-label">CLASS DEADLINE</span><h2>Everyone in one save</h2></div><small>{students.length} student{students.length===1?'':'s'} follow these dates unless adjusted.</small></div><div className="stack-list">{lessons.map(x=>{const base=classDue(x.id),own=overrides.filter(o=>o.lessonId===x.id);return <article className="management-row" key={x.id}><span className="management-icon"><FileText/></span><div><strong>{x.title}</strong><p>{base?.dueAt?formatWhen(base.dueAt):'No class deadline'} · {own.length} personal adjustment{own.length===1?'':'s'}</p></div><div className="row-actions"><button className="btn ghost small" onClick={()=>{setMsg('');setClassEdit({lessonId:x.id,lessonTitle:x.title,dueAt:base?.dueAt||''})}}><Pencil/> {base?.dueAt?'Change':'Set'}</button>{base&&<button className="btn danger small" onClick={()=>removeClass(x.id)}><Trash2/></button>}</div></article>})}{!lessons.length&&<Empty title="Add lessons before setting deadlines"/>}</div></section>
    <section className="panel section-gap"><div className="section-row"><div><span className="mini-label">PERSONAL ADJUSTMENT</span><h2>One student at a time</h2></div><button className="btn primary small" onClick={()=>{setMsg('');setOverrideEdit(blankOverride())}} disabled={!lessons.length||!students.length}><Plus/> Add adjustment</button></div>
      <div className="stack-list">{overrides.map(o=><article className="management-row" key={o.id}><span className="management-icon"><Users/></span><div><strong>{o.studentName||o.userId}</strong><p>{o.lessonTitle||lessons.find(x=>x.id===o.lessonId)?.title||'Lesson'} · {formatWhen(o.dueAt)}{o.reason?` · ${o.reason}`:''}</p></div><div className="row-actions"><button className="icon-btn danger-soft" onClick={()=>removeOverride(o.id)}><Trash2/></button></div></article>)}{!overrides.length&&<Empty title="No personal deadlines yet" text="Every student currently follows the class deadline."/>}</div>
    </section>
    <Modal open={!!classEdit} title="Class deadline (applies to all students)" onClose={()=>setClassEdit(null)}>
      <Field label="Lesson"><input value={classEdit?.lessonTitle||''} readOnly/></Field>
      <Field label="Due date and time" hint="Applies to every student in this class."><input type="datetime-local" value={classEdit?.dueAt?toLocalInput(classEdit.dueAt):''} onChange={e=>setClassEdit(v=>({...v,dueAt:e.target.value}))}/></Field>
      <Notice type="error">{msg.includes('Unable')?msg:''}</Notice>
      <div className="modal-actions"><button className="btn ghost" onClick={()=>setClassEdit(null)}>Cancel</button><button className="btn primary" onClick={saveClass}><Save/> Save deadline</button></div>
    </Modal>
    <Modal open={!!overrideEdit} title="Personal deadline" onClose={()=>setOverrideEdit(null)}>
      <Field label="Student"><select value={overrideEdit?.studentId||''} onChange={e=>setOverrideEdit(v=>({...v,studentId:e.target.value}))}>{students.map(s=><option value={s.id} key={s.id}>{s.fullname||s.email}</option>)}</select></Field>
      <Field label="Lesson"><select value={overrideEdit?.lessonId||''} onChange={e=>setOverrideEdit(v=>({...v,lessonId:e.target.value}))}>{lessons.map(x=><option value={x.id} key={x.id}>{x.title}</option>)}</select></Field>
      <Field label="New due date and time"><input type="datetime-local" value={overrideEdit?.dueAt?toLocalInput(overrideEdit.dueAt):''} onChange={e=>setOverrideEdit(v=>({...v,dueAt:e.target.value}))}/></Field>
      <Field label="Reason (optional)"><input value={overrideEdit?.reason||''} onChange={e=>setOverrideEdit(v=>({...v,reason:e.target.value}))} placeholder="Medical leave, approved extension…"/></Field>
      <Notice type="error">{msg.includes('Unable')?msg:''}</Notice>
      <div className="modal-actions"><button className="btn ghost" onClick={()=>setOverrideEdit(null)}>Cancel</button><button className="btn primary" onClick={saveOverride}><Save/> Save adjustment</button></div>
    </Modal>
  </AppShell>
}
